import { type paths } from './schema'

// Types come from the backend's OpenAPI document (schema.d.ts, generated by
// `pnpm api:types`). They are picked by path, not by schema name, so a
// renamed DTO on the backend does not break the frontend.
type JsonOf<T> = T extends {
    content: {
        'application/json': infer Body
    }
}
    ? Body
    : never

export type Note = JsonOf<paths['/api/v1/notes/{id}']['get']['responses'][200]>
export type NotePage = JsonOf<paths['/api/v1/notes']['get']['responses'][200]>
export type ListNotesQuery = NonNullable<paths['/api/v1/notes']['get']['parameters']['query']>
export type CreateNoteInput = JsonOf<paths['/api/v1/notes']['post']['requestBody']>
export type NoteStats = JsonOf<paths['/api/v1/notes/stats']['get']['responses'][200]>
